export type AppEnv = "development" | "test" | "staging" | "production";

export interface EnvProfile {
  name: AppEnv;
  patientDataSource: "synthetic" | "prod-snapshot" | "live";
  smsProvider: "console" | "twilio";
  redirectSmsTo: string | null;
  reminderLeadHours: number;
}

export function resolveEnv(raw: string | undefined): AppEnv {
  switch (raw) {
    case "development":
    case "test":
    case "staging":
    case "production":
      return raw;
    case undefined:
    case "":
      return "development";
    default:
      throw new Error(`unknown APP_ENV "${raw}"`);
  }
}

export function buildProfile(env: NodeJS.ProcessEnv): EnvProfile {
  const name = resolveEnv(env.APP_ENV);
  const dataSource: EnvProfile["patientDataSource"] =
    name === "production" ? "live" : name === "staging" ? "prod-snapshot" : "synthetic";

  const smsProvider = name === "development" || name === "test" ? "console" : "twilio";

  let redirectSmsTo: string | null = null;
  if (name !== "production" && name !== "staging") {
    redirectSmsTo = env.QA_SMS_INBOX ?? "+15550000000";
  }

  return {
    name,
    patientDataSource: dataSource,
    smsProvider,
    redirectSmsTo,
    reminderLeadHours: name === "production" ? 24 : 1,
  };
}

import { EnvProfile } from "./envProfile";

export interface Appointment {
  id: string;
  patientPhone: string;
  clinicName: string;
  startsAt: Date;
}

export interface SmsSender {
  send(to: string, body: string): Promise<void>;
}

export class ConsoleSms implements SmsSender {
  async send(to: string, body: string): Promise<void> {
    console.log(JSON.stringify({ channel: "sms", to, length: body.length }));
  }
}

export class ReminderService {
  constructor(
    private readonly profile: EnvProfile,
    private readonly sms: SmsSender,
    private readonly now: () => Date = () => new Date(),
  ) {}

  due(appointments: Appointment[]): Appointment[] {
    const horizon = this.now().getTime() + this.profile.reminderLeadHours * 3_600_000;
    return appointments.filter(
      (a) => a.startsAt.getTime() > this.now().getTime() && a.startsAt.getTime() <= horizon,
    );
  }

  async sendReminders(appointments: Appointment[]): Promise<number> {
    let sent = 0;
    for (const appt of this.due(appointments)) {
      const to = this.profile.redirectSmsTo ?? appt.patientPhone;
      const when = appt.startsAt.toISOString().slice(0, 16).replace("T", " ");
      try {
        await this.sms.send(to, `Reminder: appointment at ${appt.clinicName} on ${when} UTC. Reply C to confirm.`);
        sent++;
      } catch (err) {
        console.error(JSON.stringify({ msg: "reminder failed", appointmentId: appt.id, error: (err as Error).message }));
      }
    }
    return sent;
  }
}
